import{_ as l,l as n,o as a,c as d,v as o,p as s,x as r,d as i,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"BERT 编码器结构","description":"","frontmatter":{"title":"BERT 编码器结构","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/bert-encoder.md","filePath":"llm/bert-encoder.md","lastUpdated":1789023840000}'),A={name:"llm/bert-encoder.md"};function m(B,e,p,h,T,S){const t=n("Mermaid");return a(),d("div",null,[e[1]||(e[1]=o('<h1 id="bert-编码器结构" tabindex="-1">BERT 编码器结构 <a class="header-anchor" href="#bert-编码器结构" aria-label="Permalink to &quot;BERT 编码器结构&quot;">​</a></h1><div class="epigraph"><p>我们用掩码语言模型预训练一个深层双向 Transformer 编码器，使每个位置的表示同时条件于左右两侧。</p><footer>—— Devlin et al., BERT: Pre-training of Deep Bidirectional Transformers for Language Understanding, NAACL 2019</footer></div><p><a href="/llm/task-arithmetic">上一课</a>把权重空间里的任务向量当一等对象：差值可以加减、可以在检查点之间迁移。那一课默认的主干仍是因果解码器。补层「架构进阶」从这里改对象：纯解码器没有把<strong>编码器</strong>和<strong>编解码器</strong>写成可替换的计算图，双向自注意力、段嵌入、<code>[CLS]</code> 池化都被当成历史脚注。本课把 BERT 的编码器栈收成后课默认会用的结构；<a href="/llm/masked-lm">掩码语言模型</a>只讲目标，不讲这块栈。后课的相对偏置、去噪编解码、前缀掩码，都假定你会本课的层序，不再从「什么是双向」讲起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/causal-self-attention">因果自注意力</a>强制位置 \\(t\\) 只读 \\(j\\le t\\)。生成需要这条约束；判别、检索、把整段源句压成记忆，则需要相反的连通性：位置 \\(i\\) 的查询打到整段键。训练基础课把优化、缩放、合并都建在解码器只模型上，留下的缺口是——<strong>同一套</strong> <a href="/llm/sdpa">SDPA</a> 与 <a href="/llm/mha">多头</a>，掩码拿掉之后，栈还要哪些槽位才构成一个能微调的编码器。</p><p>缺口不是再推一遍缩放点积。缺口是三件解码器里没有或用法不同的东西：全可见自注意力、句对的段嵌入、专供分类的 <code>[CLS]</code> 位置。没有它们，后面的嵌入池化、前缀掩码都会没有落点。</p><p><span class="marginnote">BERT 原文的位置编码是可学习绝对位置，最长 512，与正弦位置不是同一课。本课只把位置槽位当成编码器的一部分，不重写外推。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一层编码器是：双向多头自注意力，接残差与层归一化，再接位置级前馈，再残差。没有交叉注意力子层，也没有因果上三角。输入是 token 嵌入、位置嵌入、段嵌入三者相加；段嵌入区分句对里的第一句与第二句。序列头部放 <code>[CLS]</code>，尾部与句间放 <code>[SEP]</code>。</p><p>预训练时每个位置仍出隐状态，<a href="/llm/masked-lm">MLM</a> 头只在被挖位置上分类；NSP 头吃 <code>[CLS]</code>。微调时 MLM 头丢掉，分类、抽取接在 <code>[CLS]</code> 或各 token 上。后课默认：说「BERT 编码器」就是指这套<strong>无交叉注意力的双向栈</strong>，不是泛指任何 Transformer。</p><h3 id="与解码器层的槽位差" tabindex="-1">与解码器层的槽位差 <a class="header-anchor" href="#与解码器层的槽位差" aria-label="Permalink to &quot;与解码器层的槽位差&quot;">​</a></h3><p>解码器一层通常是掩码自注意力、可选的读源端注意力、前馈。编码器一层少中间那块，自注意力也不掩未来。参数量按层计会更省，但源端长度 \\(m\\) 上仍是 \\(\\Theta(m^2)\\) 的分数矩阵。这不是本课要改的复杂度，只是后课比较编解码与纯解码时要用的事实。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>双向注意力让位置 \\(i\\) 的表示成为整句的函数。<code>[MASK]</code> 占位不泄漏原词，却保留「这里有一个被查询的槽」。段嵌入把句对相对位置写进加法，不必改掩码形状。<code>[CLS]</code> 没有语言学身份，它是一个可学习的汇合查询：各层都在读全句，最后一层的该向量被当成句级特征。</p><p>深度上 BERT-base 12 层、BERT-large 24 层，头数与隐宽度按 \\(d_k=64\\) 对齐。后课不需要背这些型号，需要记住：<strong>深度用来叠双向交互，宽度用来分头</strong>，没有编码器–解码器之间的交叉对齐。</p><p><span class="marginnote">双向不是「两个单向拼起来」。ELMo 的左右 LSTM 参数不共享、交互只发生在拼接之后。BERT 的每一层里左右已经在同一套 \\(Q,K,V\\) 里相遇。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>编码器默认假设整段输入在前向开始时已经齐。流式、自回归生成不能直接逐步采样；要生成得改目标或外接解码器。<code>[CLS]</code> 作句向量在分类上可用，作语义检索往往不如后课的均值池化。绝对位置 512 把长文档挡在训练分布外，这是结构承诺，不是优化失败。</p>',18)),(a(),s(c,null,{default:r(()=>[E(t,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20Tok%5B%22Token%20%E5%B5%8C%E5%85%A5%22%5D%20--%3E%20Sum%5B%22%E4%B8%89%E8%80%85%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20Pos%5B%22%E4%BD%8D%E7%BD%AE%E5%B5%8C%E5%85%A5%22%5D%20--%3E%20Sum%0A%20%20Seg%5B%22%E6%AE%B5%E5%B5%8C%E5%85%A5%22%5D%20--%3E%20Sum%0A%20%20Sum%20--%3E%20SA%5B%22%E5%8F%8C%E5%90%91%E5%A4%9A%E5%A4%B4%E8%87%AA%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20SA%20--%3E%20FF%5B%22%E4%BD%8D%E7%BD%AE%E7%BA%A7%E5%89%8D%E9%A6%88%22%5D%0A%20%20FF%20--%3E%20H%5B%22%E5%90%84%E4%BD%8D%E7%BD%AE%E8%A1%A8%E7%A4%BA%22%5D%0A%20%20H%20--%3E%20CLS%5B%22CLS%20%E5%8F%A5%E7%BA%A7%E5%A4%B4%22%5D%0A%20%20H%20--%3E%20MLM%5B%22%E8%A2%AB%E6%8E%A9%E4%BD%8D%E7%BD%AE%E7%9A%84%E8%AF%8D%E8%A1%A8%E5%A4%B4%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课把 BERT 编码器收成：双向自注意力加前馈的栈，外加段嵌入与 <code>[CLS]</code>；后课默认不再解释这套槽位。</li><li>相对因果解码器，差别不在 SDPA 公式，而在掩码、交叉注意力缺席、句级汇合方式。</li><li><code>[CLS]</code> 是可学习的句级查询，不是语义检索的默认池化。</li><li>编码器假定源序列一次给齐，不能代替自回归生成。</li><li>出处：Devlin et al., <em>BERT</em>, NAACL 2019。</li></ul>',2))])}const D=l(A,[["render",m]]);export{f as __pageData,D as default};
